package matrix

import (
	"errors"
	"strconv"
	"strings"
)

// Matrix is a rectangular grid of integers. It is a pointer type so that
// a zero value compares equal to nil.
type Matrix *matrix

type matrix struct {
	data [][]int
}

// New parses s, a string containing a matrix of numbers, into a Matrix.
//
// The string is a series of rows separated by newlines, each containing
// one or more whitespace-separated integers. All rows must have the same
// number of fields, and every field must be a valid integer.
func New(s string) (Matrix, error) {
	lines := strings.Split(s, "\n")
	data := make([][]int, len(lines))
	width := 0
	for i, line := range lines {
		fields := strings.Fields(line)
		if len(fields) == 0 {
			return nil, errors.New("matrix: row must not be empty")
		}
		row := make([]int, len(fields))
		for j, f := range fields {
			v, err := strconv.Atoi(f)
			if err != nil {
				return nil, err
			}
			row[j] = v
		}
		if width == 0 {
			width = len(row)
		} else if len(row) != width {
			return nil, errors.New("matrix: uneven rows")
		}
		data[i] = row
	}
	return (*matrix)(&matrix{data: data}), nil
}

// Cols returns the columns of the matrix as a copy of the element data;
// mutating the result does not affect the matrix.
func (m Matrix) Cols() [][]int {
	if m == nil || len(m.data) == 0 {
		return nil
	}
	width := len(m.data[0])
	cols := make([][]int, width)
	for c := range cols {
		cols[c] = make([]int, len(m.data))
		for r, row := range m.data {
			cols[c][r] = row[c]
		}
	}
	return cols
}

// Rows returns the rows of the matrix as a copy of the element data;
// mutating the result does not affect the matrix.
func (m Matrix) Rows() [][]int {
	if m == nil {
		return nil
	}
	rows := make([][]int, len(m.data))
	for i, row := range m.data {
		rows[i] = append([]int(nil), row...)
	}
	return rows
}

// Set sets the element at (row, col) to val. It returns true on success
// and false if the coordinates are out of range.
func (m Matrix) Set(row, col, val int) bool {
	if m == nil || row < 0 || row >= len(m.data) || col < 0 || col >= len(m.data[row]) {
		return false
	}
	m.data[row][col] = val
	return true
}

