// Cols returns the columns of the matrix as a copy of the element data.
func (m *matrix) Cols() [][]int {
	if len(m.data) == 0 {
		return nil
	}
	width := len(m.data[0])
	cols := make([][]int, width)
	for c := range cols {
		cols[c] = make([]int, len(m.data))
		for r, row := range m.data {
			cols[c][r] = row[c]
		}
	}
	return cols
}

// Rows returns the rows of the matrix as a copy of the element data.
func (m *matrix) Rows() [][]int {
	rows := make([][]int, len(m.data))
	for i, row := range m.data {
		rows[i] = append([]int(nil), row...)
	}
	return rows
}

// Set sets the element at (row, col) to val, or returns false if the
// coordinates are out of range.
func (m *matrix) Set(row, col, val int) bool {
	if row < 0 || row >= len(m.data) || col < 0 || col >= len(m.data[row]) {
		return false
	}
	m.data[row][col] = val
	return true
}
